const state={page:'home',theme:localStorage.getItem('statslab-theme')==='dark'?'dark':'light',values:{},data:{},ran:{}};
for(const [id,mod] of Object.entries(modules)){state.values[id]={};for(const c of mod.controls)state.values[id][c.id]=c.value;}
const el=id=>document.getElementById(id);
const num=x=>Number(x),fmt=(x,d=3)=>Number.isFinite(x)?x.toFixed(d):'N/A',sig=x=>Number.isFinite(x)?x<.001?'< .001':x.toFixed(3):'N/A',pct=(x,d=1)=>Number.isFinite(x)?`${(100*x).toFixed(d)}%`:'N/A';
const htmlEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function metrics(items){return `<div class="metric-grid">${items.map(m=>`<div class="metric"><div class="metric-label">${htmlEscape(m[0])}</div><div class="metric-value">${htmlEscape(m[1])}</div><div class="metric-sub">${htmlEscape(m[2]||'')}</div></div>`).join('')}</div>`}
function plotCard(id,title,sub='',cls=''){return `<section class="plot-card"><div class="plot-title">${title}</div>${sub?`<p class="plot-sub">${sub}</p>`:''}<div id="${id}" class="plot ${cls}"></div></section>`}
function tableCard(title,rows,limit=60){if(!rows?.length)return '';const keys=Object.keys(rows[0]);return `<section class="table-card"><div class="panel-title">${htmlEscape(title)}</div><div class="scroll-table"><table class="data-table"><thead><tr>${keys.map(k=>`<th>${htmlEscape(k)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map(row=>`<tr>${keys.map(k=>`<td>${htmlEscape(row[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${rows.length>limit?`<p class="muted" style="font-size:11px">Menampilkan ${limit} dari ${rows.length} baris. Gunakan CSV untuk seluruh data.</p>`:''}</section>`}
function interpret(content){return `<section class="interpret"><h3>Interpretasi</h3>${content}</section>`}
function note(msg){return `<div class="insight">${msg}</div>`}
const P=()=>{let d=state.theme==='dark';return d?{fg:'#e2ecf5',muted:'#a1b4c6',grid:'#334759',blue:'#87bbeb',teal:'#7fd0bd',amber:'#f0c67d',red:'#e99393',hist:'#65798b',point:'#d9e4f0',paper:'#1a2531',fill:'rgba(130,189,238,.15)'}:{fg:'#2a4053',muted:'#738797',grid:'#e0e8ee',blue:'#367dab',teal:'#2d937d',amber:'#bb8b2d',red:'#bd5e61',hist:'#c7d4df',point:'#31485c',paper:'#ffffff',fill:'rgba(70,145,203,.15)'}};
function chart(id,traces,extra={}){let p=P();let node=el(id);if(!node)return;let layout={autosize:true,height:node.clientHeight||320,margin:{l:51,r:17,t:12,b:53},paper_bgcolor:p.paper,plot_bgcolor:p.paper,font:{family:'-apple-system,BlinkMacSystemFont,Segoe UI,Arial',color:p.muted,size:11},xaxis:{gridcolor:p.grid,zerolinecolor:p.grid,showline:true,linecolor:p.grid},yaxis:{gridcolor:p.grid,zerolinecolor:p.grid,showline:true,linecolor:p.grid},showlegend:false,hovermode:'closest',...extra};Plotly.react(node,traces,layout,{responsive:true,displaylogo:false,modeBarButtonsToRemove:['select2d','lasso2d','autoScale2d','toggleSpikelines','toImage'],displayModeBar:false});}
function histTrace(values,nbins=36){return {type:'histogram',x:values,nbinsx:nbins,marker:{color:P().hist,line:{color:P().paper,width:1}},hovertemplate:'x: %{x:.3f}<br>Count: %{y}<extra></extra>'}}
const line=(x,y,color=P().blue,extra={})=>({type:'scatter',mode:'lines',x,y,line:{color,width:2,...extra},hoverinfo:'skip'});
const scatter=(x,y,color=P().point,extra={})=>({type:'scatter',mode:'markers',x,y,marker:{size:6,opacity:.72,color,...extra}});
const vline=(x,color=P().blue,dash='dash')=>({type:'line',x0:x,x1:x,y0:0,y1:1,xref:'x',yref:'paper',line:{color,dash,width:1.5}});
const hline=(y,color=P().fg,dash='dash')=>({type:'line',x0:0,x1:1,xref:'paper',y0:y,y1:y,yref:'y',line:{color,dash,width:1.5}});
function runCharts(funcs){for(const f of funcs){try{f()}catch(e){console.error('Chart error',e)}}}
function addCSV(rows,filename){let keys=Object.keys(rows[0]||{}),csv=[keys.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')];for(let row of rows){csv.push(keys.map(k=>`"${String(row[k]??'').replaceAll('"','""')}"`).join(','));}const blob=new Blob(['\ufeff'+csv.join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2500)}
function renderControl(c,value){let id=`c_${c.id}`,label=`<span>${htmlEscape(c.label)}${c.type==='range'?` <b id="r_${c.id}" class="range-meta">${fmtInput(value)}</b>`:''}</span>`,valueHtml=htmlEscape(value);let body;if(c.type==='select')body=`<select id="${id}">${c.options.map(o=>`<option value="${htmlEscape(o.value)}" ${o.value===value?'selected':''}>${htmlEscape(o.label)}</option>`).join('')}</select>`;else if(c.type==='range')body=`<input type="range" id="${id}" min="${c.min}" max="${c.max}" step="${c.step}" value="${valueHtml}">`;else if(c.type==='check')return `<label class="control check" data-control="${c.id}"><input type="checkbox" id="${id}" ${value?'checked':''}><span>${htmlEscape(c.label)}</span></label>`;else body=`<input type="number" id="${id}" value="${valueHtml}" min="${c.min}" step="${c.step}">`;return `<label class="control" data-control="${c.id}">${label}${body}</label>`}
function fmtInput(x){return Number.isInteger(x)?String(x):Number(x).toFixed(Math.abs(x)<.1?3:2).replace(/0+$/,'').replace(/\.$/,'')}
function getInputs(page){let val=state.values[page],m=modules[page];for(const c of m.controls){let dom=el(`c_${c.id}`);if(dom){val[c.id]=c.type==='check'?dom.checked:c.type==='select'?dom.value:num(dom.value)}}return val}
function validateInputs(page,v){for(const c of modules[page].controls){if(c.type==='select'||c.type==='check'||(c.show&&!c.show(v)))continue;let x=v[c.id];if(!Number.isFinite(x)||(c.min!==undefined&&x<c.min)||(c.max!==undefined&&x>c.max))throw Error(`Periksa parameter "${c.label}": nilainya harus valid.`);if(c.type==='number'&&['n1','n2','np','no','seed'].includes(c.id)&&x%1!==0)throw Error(`${c.label} harus bilangan bulat.`);}if(page==='ttest'){for(const n of ['n1','n2','np','no'])if(v[n]>2000)throw Error('Maksimum 2.000 observasi per grup agar browser tetap responsif.');}}
function refreshControls(page){let v=getInputs(page);if(page==='power'){let c=el('c_effect');let isAnova=v.test==='One-way ANOVA';let label=c.closest('label').querySelector('span');label.childNodes[0].textContent=`Effect size (Cohen’s ${isAnova?'f':v.test==='Paired t-test'?'dz':'d'})`;c.max=isAnova?.8:1.5;c.step=isAnova?.01:.05;if(v.effect>num(c.max)){v.effect=num(c.max);c.value=v.effect;}el('r_effect').textContent=fmtInput(v.effect)}for(const c of modules[page].controls){let element=document.querySelector(`[data-control="${c.id}"]`);if(element)element.hidden=!!(c.show&&!c.show(v));if(c.type==='range'&&el(`r_${c.id}`))el(`r_${c.id}`).textContent=fmtInput(v[c.id]);}}
function applyPreset(page,name){let preset=modules[page].presets[name];if(!preset)return;let v=state.values[page];Object.assign(v,preset);for(const c of modules[page].controls){let dom=el(`c_${c.id}`);if(!dom)continue;if(c.type==='check')dom.checked=!!v[c.id];else dom.value=v[c.id];}refreshControls(page)}
function run(page){let node=el('results'),b=el('runBtn');if(!node)return;try{if(b){b.disabled=true;b.textContent='Menghitung…'}let v={...getInputs(page)};validateInputs(page,v);const data=computations[page](v);state.data[page]=data;state.ran[page]=true;node.innerHTML=renderResults[page](data,v);let rows=data.export||[];if(rows.length){node.insertAdjacentHTML('afterbegin',`<div class="export-row" style="margin-bottom:12px"><button class="outline-btn" type="button" id="downloadCsv">↓ Export all simulated data (CSV)</button></div>`);el('downloadCsv').addEventListener('click',()=>addCSV(rows,`statistics-lab-${page}.csv`));}renderPlots[page](data,v);}catch(e){node.innerHTML=`<div class="error-panel"><b>Simulasi tidak dapat dijalankan</b><p>${htmlEscape(e.message||e)}</p></div>`;console.error(e)}finally{if(b){b.disabled=false;b.textContent=page==='power'?'Update analysis':'Generate & analyze'}}}
function go(page,push=true){if(!modules[page]&&page!=='home'&&page!=='guide')page='home';state.page=page;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));el('sidebar').classList.remove('show');let main=el('main');if(page==='home')main.innerHTML=homeHTML();else if(page==='guide')main.innerHTML=guideHTML();else{let m=modules[page],v=state.values[page];main.innerHTML=`<div class="module-heading"><div class="big-symbol">${m.icon}</div><div><div class="eyebrow">${m.category} · Interactive lab</div><h1>${m.title}</h1><p>${m.desc}</p></div></div><details class="learning"><summary>Apa yang dipelajari di bagian ini?</summary><div class="learning-body"><ul>${m.learn.map(s=>`<li>${htmlEscape(s)}</li>`).join('')}</ul><div class="try"><strong>Eksperimen yang disarankan:</strong> ${htmlEscape(m.try)}</div></div></details><div class="workspace"><aside class="controls"><h3>⚙ Experiment setup</h3><div class="preset-area"><label class="control"><span>Experiment preset</span><select id="preset"><option value="Custom">Custom</option>${Object.keys(m.presets).map(k=>`<option>${htmlEscape(k)}</option>`).join('')}</select></label></div>${m.controls.map(c=>renderControl(c,v[c.id])).join('')}<button class="run-btn" id="runBtn" type="button">${page==='power'?'Update analysis':'Generate & analyze'}</button><p class="control-hint">Ubah parameter dan klik tombol untuk melihat simulasi baru. Random seed yang sama menghasilkan hasil yang sama untuk konfigurasi yang sama.</p></aside><div id="results" class="results"><div class="loader">Menyiapkan simulasi…</div></div></div>`;el('preset').addEventListener('change',e=>{applyPreset(page,e.target.value);run(page)});m.controls.forEach(c=>{let input=el(`c_${c.id}`);input.addEventListener('input',()=>{refreshControls(page);if(page==='power'&&c.id!=='seed')run(page)});if(c.type==='select'||c.type==='check')input.addEventListener('change',()=>{refreshControls(page);if(c.id==='type'||c.id==='test')run(page)});});el('runBtn').addEventListener('click',()=>run(page));refreshControls(page);setTimeout(()=>run(page),5)}if(push&&location.hash!==`#${page}`)history.pushState(null,'',`#${page}`);window.scrollTo({top:0,behavior:'instant'})}
function homeHTML(){let sections=[['Foundations of inference',['sampling','ci','pvalue','power']],['Relationships',['correlation','regression']],['Group comparisons',['ttest','anova']]];return `<section class="hero"><div class="eyebrow">STATISTICS · INTERACTIVE LEARNING</div><h1>Statistics Learning Lab</h1><p>Laboratorium interaktif untuk memahami konsep inti statistika melalui simulasi. Ubah parameter, bandingkan skenario, dan amati bagaimana effect size, sample size, variability, serta assumptions memengaruhi hasil statistik.</p><div class="hero-mini"><span class="mini-chip">08 interactive modules</span><span class="mini-chip">Runs entirely in your browser</span><span class="mini-chip">No account needed</span><span class="mini-chip">CSV export</span></div></section><div class="callout">Cara belajar: pilih satu modul → gunakan <strong>Experiment preset</strong> → ubah satu parameter → klik <strong>Generate & analyze</strong> → bandingkan grafik dan interpretasinya. Ini adalah alat pembelajaran berbasis data simulasi, bukan pengganti analisis penelitian yang mempertimbangkan desain serta asumsi.</div>${sections.map(([heading,ids])=>`<h2 class="section-heading">${heading}</h2><div class="module-grid ${ids.length===2?'two':''}">${ids.map(id=>{let m=modules[id];return `<button type="button" class="mod-card" data-open="${id}"><span class="mod-symbol">${m.icon}</span><strong>${m.title}</strong><span class="desc">${m.short}</span><span class="open">Explore module →</span></button>`}).join('')}</div>`).join('')}<div class="footer-main">© 2026 Hanif Akhtar · Statistics Learning Lab · <a href="#guide">Panduan & referensi</a></div>`}
function guideHTML(){return `<div class="hero"><div class="eyebrow">DOCUMENTATION</div><h1>Panduan & Referensi</h1><p>Statistik dipelajari dengan memodifikasi parameter, menjalankan repeated simulations, dan memeriksa pola output.</p></div><div class="guide-content"><section class="info-card"><h2>Cara menggunakan</h2><ol><li>Buka modul dari menu di samping atau beranda.</li><li>Pilih <strong>Experiment preset</strong> atau sesuaikan parameter manual.</li><li>Klik <strong>Generate & analyze</strong>. Untuk Statistical Power, grafik diperbarui otomatis.</li><li>Amati metrics, plots, data tables, dan interpretasi. Gunakan tombol <strong>Export CSV</strong> jika tersedia.</li><li>Gunakan <strong>Random seed</strong> sama untuk reproducible simulation (seed generator browser berbeda dari generator R).</li></ol></section><section class="info-card"><h2>Catatan akurasi dan cakupan</h2><p>Perhitungan t-test, regresi linear dan ANOVA memakai rumus statistik standar di JavaScript. Tail probabilities dihitung melalui incomplete beta, bukan server R. Statistical Power untuk t-test memakai <strong>pendekatan numerik noncentral-t</strong> (dengan aproksimasi Wilson–Hilferty untuk distribusi chi-square), sehingga angka dapat sedikit berbeda dari <code>power.t.test()</code> di R. Power ANOVA menggunakan distribusi noncentral F melalui Poisson mixture.</p><p>Tukey HSD memakai interpolasi tabel numerik studentized-range yang dibuat dari SciPy. Hasil post hoc merupakan aproksimasi kecil karena interpolasi dan perlu dikonfirmasi dengan perangkat lunak statistik untuk analisis penelitian.</p><p>Semua data simulasi diproses <strong>secara lokal di browser</strong> dan tidak dikirim ke server. Plotly.js dibundel di folder <code>assets</code>, sehingga grafik tidak membutuhkan CDN.</p></section><section class="info-card"><h2>Topik</h2>${Object.values(modules).map(m=>`<p><strong>${m.title}</strong> — ${m.short}</p>`).join('')}</section><section class="info-card"><h2>Referensi metodologis</h2><ul><li>Cohen, J. (1988). <em>Statistical Power Analysis for the Behavioral Sciences</em> (2nd ed.).</li><li>Casella, G., & Berger, R. L. (2002). <em>Statistical Inference</em> (2nd ed.).</li><li>Efron, B., & Tibshirani, R. J. (1993). <em>An Introduction to the Bootstrap</em>.</li><li>Wasserman, L. (2004). <em>All of Statistics</em>.</li><li>R Core Team. <em>R: A Language and Environment for Statistical Computing</em> (functions referenced by the original Shiny application).</li></ul></section></div>`}
const computations={
 sampling(v){let R=S.rng(v.seed),population=S.popDraw(10000,v.dist,v.mu,v.sigma,R),one=S.popDraw(v.n,v.dist,v.mu,v.sigma,R),stats=[];for(let i=0;i<v.reps;i++){let x=S.popDraw(v.n,v.dist,v.mu,v.sigma,R);stats.push(v.stat==='Mean'?S.mean(x):S.median(x));}let target=v.stat==='Mean'?v.mu:S.median(population);return{population,one,stats,target,center:S.mean(stats),empSE:S.sd(stats),theoSE:v.stat==='Mean'?v.sigma/Math.sqrt(v.n):NaN,export:stats.map((x,i)=>({sample:i+1,statistic:x}))}},
 ci(v){let R=S.rng(v.seed),tcrit=S.studentInv((1+v.level)/2,v.n-1),rows=[];for(let i=0;i<v.reps;i++){let sample=S.popDraw(v.n,v.dist,v.mu,v.sigma,R),m=S.mean(sample),width=2*tcrit*S.sd(sample)/Math.sqrt(v.n),lower=m-width/2,upper=m+width/2;rows.push({iteration:i+1,mean:m,lower,upper,covered:lower<=v.mu&&upper>=v.mu,width})}return{rows,coverage:rows.filter(r=>r.covered).length/rows.length,meanWidth:S.mean(rows.map(r=>r.width)),export:rows.map(r=>({...r,covered:r.covered?'Yes':'No'}))}},
 pvalue(v){let R=S.rng(v.seed),rows=[];for(let i=0;i<v.reps;i++){let m1=R.normal()/Math.sqrt(v.n),m2=v.d+R.normal()/Math.sqrt(v.n),s1=R.chi2(v.n-1)/(v.n-1),s2=R.chi2(v.n-1)/(v.n-1),se=Math.sqrt((s1+s2)/v.n),estimate=m2-m1,t=estimate/se,df=(s1+s2)**2/(s1*s1+s2*s2)*(v.n-1),p=S.clamp(2*(1-S.studentCDF(Math.abs(t),df)),0,1);rows.push({study:i+1,estimate,t,df,p,significant:p<v.alpha})}return{rows,significant:S.mean(rows.map(r=>Number(r.significant))),power:S.powerT(v.n,v.d,v.alpha),medianP:S.median(rows.map(r=>r.p)),meanEffect:S.mean(rows.map(r=>r.estimate)),export:rows.map(r=>({...r,significant:r.significant?'Yes':'No'}))}},
 power(v){let isA=v.test==='One-way ANOVA',paired=v.test==='Paired t-test',powerFn=(n,eff)=>isA?S.powerF(v.groups,n,eff,v.alpha):S.powerT(n,eff,v.alpha,paired),current=powerFn(v.n,v.effect),needed=S.requiredN(n=>powerFn(n,v.effect),v.target),ns=Array.from({length:60},(_,i)=>(i+1)*5),effects=Array.from({length:70},(_,i)=>.05+i*((isA?.8:1.5)-.05)/69);return{current,needed,ns,powersN:ns.map(n=>powerFn(n,v.effect)),effects,powersE:effects.map(effect=>powerFn(v.n,effect)),export:ns.map((n,i)=>({n,power:powerFn(n,v.effect)}))};},
 correlation(v){let R=S.rng(v.seed),pool=Math.max(v.n*8,2000),xx=Array.from({length:pool},()=>R.normal()),yy=[];if(v.shape==='Linear'){for(let i=0;i<pool;i++)yy.push(v.r*xx[i]+Math.sqrt(Math.max(0,1-v.r*v.r))*R.normal())}else{const raw=xx.map(x=>v.shape==='U-shaped'?x*x:x*x*x),mu=S.mean(raw),sc=S.sd(raw),mixed=raw.map(x=>(x-mu)/sc+R.normal()*v.noise),mm=S.mean(mixed),ss=S.sd(mixed);yy=mixed.map(x=>(x-mm)/ss)}let xMin=S.quantile(xx,(1-v.range/100)/2),xMax=S.quantile(xx,1-(1-v.range/100)/2),eligible=Array.from({length:pool},(_,i)=>i).filter(i=>xx[i]>=xMin&&xx[i]<=xMax);for(let i=eligible.length-1;i>0;i--){let j=Math.floor(R.uniform()*(i+1));[eligible[i],eligible[j]]=[eligible[j],eligible[i]]}let x=eligible.slice(0,v.n).map(i=>xx[i]),y=eligible.slice(0,v.n).map(i=>yy[i]),point=x.map(()=>'Regular');if(v.outlier){x.push(Math.max(...x)+v.strength);y.push(Math.min(...y)-v.strength);point.push('Outlier')}let r=S.pearson(x,y),rho=S.spearman(x,y),n=x.length,t=r*Math.sqrt((n-2)/(1-r*r)),p=S.clamp(2*(1-S.studentCDF(Math.abs(t),n-2)),0,1),fit=S.linreg(x,y);let B=S.rng(v.seed+99),boots=[];for(let b=0;b<500;b++){let bx=[],by=[];for(let j=0;j<n;j++){let ix=Math.floor(B.uniform()*n);bx.push(x[ix]);by.push(y[ix])}let rb=S.pearson(bx,by);if(Number.isFinite(rb))boots.push(rb);}let useF=v.shape==='Linear'&&v.range===100&&!v.outlier,ci=useF?S.fisherCI(r,n):[S.quantile(boots,.025),S.quantile(boots,.975)],without=v.outlier?S.pearson(x.slice(0,-1),y.slice(0,-1)):NaN;return{x,y,point,r,rho,p,ci,boots,fit,without,ciMethod:useF?'Fisher z CI':'Bootstrap percentile CI',export:x.map((z,i)=>({x:z,y:y[i],point:point[i]}))}},
 regression(v){let R=S.rng(v.seed),x=Array.from({length:v.n},()=>R.normal()),quad=v.shape==='Linear'?0:v.quad,truth=x.map(t=>v.intercept+v.slope*t+quad*t*t),y=truth.map((t,i)=>t+v.sigma*(1+v.hetero*Math.abs(x[i]))*R.normal()),point=x.map(()=>'Regular');if(v.outlier){x.push(Math.max(...x)+3);y.push(Math.min(...y)-3*v.sigma);point.push('Outlier')}let fit=S.linreg(x,y),tc=S.studentInv(.975,fit.df),n=x.length,pred=fit.b0+fit.b1*v.x0,seMean=Math.sqrt(fit.s2*(1/n+(v.x0-fit.mx)**2/fit.sxx)),seInd=Math.sqrt(fit.s2+seMean*seMean),conf=[pred-tc*seMean,pred+tc*seMean],pi=[pred-tc*seInd,pred+tc*seInd],co=[{Term:'Intercept',Estimate:fit.b0,'Standard Error':fit.seIntercept,t:fit.b0/fit.seIntercept,p:2*(1-S.studentCDF(Math.abs(fit.b0/fit.seIntercept),fit.df)),Lower:fit.b0-tc*fit.seIntercept,Upper:fit.b0+tc*fit.seIntercept},{Term:'Slope',Estimate:fit.b1,'Standard Error':fit.seSlope,t:fit.t,p:fit.p,Lower:fit.b1-tc*fit.seSlope,Upper:fit.b1+tc*fit.seSlope}];let table=[...co.map(r=>({Section:'Coefficient',...r})),{Section:'Prediction',Term:'Mean response',Estimate:pred,Lower:'',Upper:''},{Section:'Prediction',Term:'95% CI for mean response',Estimate:pred,Lower:conf[0],Upper:conf[1]},{Section:'Prediction',Term:'95% Prediction Interval',Estimate:pred,Lower:pi[0],Upper:pi[1]}];return{x,y,point,fit,quad,conf,pi,pred,co,table,export:x.map((z,i)=>({x:z,y:y[i],fitted:fit.fitted[i],residual:fit.resid[i],point:point[i]}))}},
 ttest(v){let R=S.rng(v.seed),groups=[],arr=[],diff,df,t,p,d,ci,estimate,label,method=v.method;const generate=(n,mu,sd)=>Array.from({length:n},()=>mu+sd*R.normal());if(v.type==='Independent samples'){let x=generate(v.n1,v.m1,v.sd1),y=generate(v.n2,v.m2,v.sd2),m1=S.mean(x),m2=S.mean(y),s1=S.variance(x),s2=S.variance(y),pooled=Math.sqrt(((x.length-1)*s1+(y.length-1)*s2)/(x.length+y.length-2));let se;if(method==='Student'){df=x.length+y.length-2;se=pooled*Math.sqrt(1/x.length+1/y.length)}else{se=Math.sqrt(s1/x.length+s2/y.length);df=(s1/x.length+s2/y.length)**2/((s1/x.length)**2/(x.length-1)+(s2/y.length)**2/(y.length-1))}estimate=m1-m2;t=estimate/se;d=estimate/pooled;ci=[estimate-S.studentInv((1+v.conf)/2,df)*se,estimate+S.studentInv((1+v.conf)/2,df)*se];groups=[{name:'Group 1',values:x},{name:'Group 2',values:y}];label='Mean difference (Group 1 − Group 2)';}else if(v.type==='Paired samples'){let pre=[],post=[];for(let i=0;i<v.np;i++){let a=R.normal(),b=R.normal();pre.push(v.pre+v.psd*a);post.push(v.post+v.psd*(v.pr*a+Math.sqrt(1-v.pr*v.pr)*b))}diff=pre.map((t,i)=>t-post[i]);estimate=S.mean(diff);df=diff.length-1;let se=S.sd(diff)/Math.sqrt(diff.length);t=estimate/se;d=estimate/S.sd(diff);ci=[estimate-S.studentInv((1+v.conf)/2,df)*se,estimate+S.studentInv((1+v.conf)/2,df)*se];groups=[{name:'Pre',values:pre},{name:'Post',values:post}];label='Mean paired difference (Pre − Post)';}else{let x=generate(v.no,v.popmean,v.osd);estimate=S.mean(x)-v.mu0;df=x.length-1;let se=S.sd(x)/Math.sqrt(x.length);t=estimate/se;d=estimate/S.sd(x);ci=[estimate-S.studentInv((1+v.conf)/2,df)*se,estimate+S.studentInv((1+v.conf)/2,df)*se];groups=[{name:'Sample',values:x}];label='Mean difference from mu0';}p=S.clamp(2*(1-S.studentCDF(Math.abs(t),df)),0,1);let desc=groups.map(g=>({group:g.name,n:g.values.length,mean:S.mean(g.values),sd:S.sd(g.values)}));let exp=groups.flatMap(g=>g.values.map((z,i)=>({group:g.name,id:i+1,value:z})));return{groups,desc,estimate,df,t,p,d,ci,label,paired:v.type==='Paired samples',export:exp}},
 anova(v){let R=S.rng(v.seed),k=v.k,n=v.n,means=Array.from({length:k},(_,i)=>v[`m${i+1}`]),groups=means.map((mu,i)=>({name:`Group ${i+1}`,values:Array.from({length:n},()=>mu+v.sigma*R.normal()),populationMean:mu})),all=groups.flatMap(g=>g.values),grand=S.mean(all),meansObs=groups.map(g=>S.mean(g.values)),ssb=n*S.sum(meansObs.map(m=>(m-grand)**2)),ssw=S.sum(groups.map(g=>S.sum(g.values.map(x=>(x-S.mean(g.values))**2)))),sst=ssb+ssw,dfb=k-1,dfw=k*(n-1),msb=ssb/dfb,msw=ssw/dfw,F=msb/msw,p=S.clamp(1-S.fCDF(F,dfb,dfw),0,1),eta2=ssb/sst,omega2=Math.max(0,(ssb-dfb*msw)/(sst+msw)),table=[{Source:'Between Groups',SS:ssb,df:dfb,MS:msb,F,p},{Source:'Within Groups',SS:ssw,df:dfw,MS:msw,F:'',p:''},{Source:'Total',SS:sst,df:dfb+dfw,MS:'',F:'',p:''}],descs=groups.map(g=>({group:g.name,n,mean:S.mean(g.values),sd:S.sd(g.values),population_mean:g.populationMean})),tukey=[];for(let i=0;i<k;i++)for(let j=i+1;j<k;j++){let difference=meansObs[j]-meansObs[i],se=Math.sqrt(msw/n),q=Math.abs(difference)/se,crit=S.tukeyInv(v.alpha,k,dfw),padj=S.tukeySF(q,k,dfw);tukey.push({Comparison:`Group ${j+1} − Group ${i+1}`,Difference:difference,Lower:difference-crit*se,Upper:difference+crit*se,'Adjusted p':padj})}return{groups,meansObs,means,ssb,ssw,msb,msw,F,p,dfb,dfw,eta2,omega2,table,tukey,descs,export:groups.flatMap(g=>g.values.map((value,i)=>({group:g.name,id:i+1,value,population_mean:g.populationMean})))} }
};
/* table formatting helpers, retaining original rows for CSV exports */
const tableFmt=(rows,prec=4)=>rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,x])=>[k,typeof x==='number'?(Number.isInteger(x)&&!['p','Adjusted p'].includes(k)?x:fmt(x,prec)):x])));
const dataBox=(title,rows,limit=60)=>tableCard(title,tableFmt(rows),limit);
const renderResults={
 sampling(d,v){return `${metrics([['Population '+v.stat.toLowerCase(),fmt(d.target,2)],['Empirical center',fmt(d.center,2),'Mean of simulated '+v.stat],['Empirical SE',fmt(d.empSE,3)],['Theoretical SE',fmt(d.theoSE,3),v.stat==='Mean'?'SD / √n':'Not shown for median']])}<div class="viz-grid">${plotCard('sampPop','Population Distribution',v.dist)}${plotCard('sampOne','One Random Sample',`n = ${v.n}`)}</div>${plotCard('sampSim','Sampling Distribution',`${v.reps} samples of n = ${v.n}`,'tall')}${interpret(`<p>Untuk <strong>${v.reps.toLocaleString('id-ID')}</strong> repeated samples berukuran n = <strong>${v.n}</strong>, empirical Standard Error = <strong>${fmt(d.empSE)}</strong>. Population target = ${fmt(d.target,2)}.</p><p>${v.stat==='Mean'?`Theoretical SE = SD / √n = <strong>${fmt(d.theoSE)}</strong>. Empirical SE biasanya mendekati nilai ini saat jumlah simulasi meningkat.`:'Theoretical SE untuk median tidak ditampilkan karena bergantung pada bentuk distribusi populasi.'}</p>${note('Coba naikkan n, lalu lihat bagaimana distribusi statistik lebih terkonsentrasi di sekitar population target.')}`)}${dataBox('Simulated Statistics (first 60)',d.export)}`},
 ci(d,v){return `${metrics([['Target confidence',pct(v.level,0)],['Coverage rate',pct(d.coverage)],['Mean CI width',fmt(d.meanWidth,2)],['Missed intervals',String(d.rows.filter(r=>!r.covered).length),`of ${v.reps} intervals`]])}${plotCard('ciPlot','First 100 Confidence Intervals',`Dashed line = true population mean (${v.mu})`,'tall')}${interpret(`<p>Dalam <strong>${v.reps}</strong> repeated samples, <strong>${pct(d.coverage)}</strong> interval mencakup true population mean. Target confidence level adalah ${pct(v.level,0)}; selisih kecil dapat muncul akibat Monte Carlo variability.</p><p>Mean interval width = <strong>${fmt(d.meanWidth,2)}</strong>. Sample size yang lebih besar biasanya memberi interval lebih sempit.</p>${note('Frequentist interpretation: confidence level menjelaskan long-run coverage procedure, bukan probability bahwa sebuah parameter fixed ada dalam CI yang sudah dihitung.')}`)}${dataBox('Confidence Interval Results (first 60)',d.export)}`},
 pvalue(d,v){return `${metrics([['Significant rate',pct(d.significant),v.d===0?'Type I error estimate':'Empirical power'],['Analytic power (approx.)',pct(d.power),'Noncentral-t approximation'],['Median p-value',fmt(d.medianP,3)],['Mean effect estimate',fmt(d.meanEffect,3),`True difference = ${v.d}`]])}<section class="plot-card"><label class="control" style="max-width:360px"><span>Study to inspect: <b class="range-meta" id="studyLabel">1</b></span><input type="range" id="studyInput" min="1" max="${d.rows.length}" value="1"></label><div id="studyMetrics"></div><div class="plot-title">p-value as Tail Area (Single Study)</div><div class="plot tall" id="pvSingle"></div></section><div class="viz-grid">${plotCard('pvHist','Distribution of p-values',`Alpha = ${v.alpha}`)}${plotCard('pvEffects','Distribution of Effect Estimates',`True mean difference = ${v.d}`)}</div>${interpret(`<p>Setiap studi yang disimulasikan menghasilkan estimate, t statistic, dan p-value yang berbeda karena sampling variability.</p><p>${v.d===0?`Karena true effect = 0, significant rate <strong>${pct(d.significant)}</strong> merupakan estimate Type I error, yang dalam simulasi besar seharusnya mendekati alpha.`:`Dengan true effect = ${v.d}, significant rate <strong>${pct(d.significant)}</strong> adalah empirical power; perkiraan analytic power <strong>${pct(d.power)}</strong>.`}</p>${note('p-value adalah tail probability under H0, bukan probabilitas bahwa H0 benar ataupun ukuran besar efek.')}`)}${dataBox('Repeated Study Results (first 60)',d.export)}`},
 power(d,v){return `${metrics([['Estimated power',pct(d.current),'Numerical approximation'],['Beta',pct(1-d.current),'Type II error probability'],['Current n',String(v.n),v.test==='Paired t-test'?'pairs':'per group'],['Required n',d.needed===null?'Not reached':String(d.needed),`for ${pct(v.target,0)} power`]])}<div class="viz-grid">${plotCard('powN','Power by Sample Size',v.test==='Paired t-test'?'Number of pairs':'Observations per group')}${plotCard('powE','Power by Effect Size',v.test)}</div>${interpret(`<p>Estimated power saat ini <strong>${pct(d.current)}</strong> (beta = ${pct(1-d.current)}). Jika asumsi model dan true effect sesuai, itulah estimasi proporsi repeated studies yang secara statistik significant.</p><p>Untuk mencapai target power ${pct(v.target,0)}, required n diperkirakan <strong>${d.needed??'melebihi batas pencarian'}</strong> ${v.test==='Paired t-test'?'pasangan':'per grup'}.</p>${note('Perhitungan t power memakai integrasi numerik noncentral-t dengan pendekatan distribusi chi-square. Nilai bisa sedikit berbeda dari R power.t.test; gunakan program analisis power khusus untuk perencanaan penelitian final.')}`)}${dataBox('Power Curve by Sample Size',d.ns.map((n,i)=>({n,power:d.powersN[i]})))}`},
 correlation(d,v){return `${metrics([['Pearson r',fmt(d.r),'Linear association'],['Spearman rho',fmt(d.rho),'Rank monotonic association'],['Pearson p-value',sig(d.p)],['95% CI for r',`[${fmt(d.ci[0],2)}, ${fmt(d.ci[1],2)}]`,d.ciMethod]])}<div class="viz-grid wide-left">${plotCard('corrScatter','Relationship Shape',v.shape,'tall')}${plotCard('corrBoot','Bootstrap Distribution of r','500 resamples','tall')}</div>${interpret(`<p>Pearson r = <strong>${fmt(d.r)}</strong>, Spearman rho = <strong>${fmt(d.rho)}</strong>, untuk generating relationship <strong>${v.shape}</strong>.</p>${v.shape==='Linear'?`<p>Population r sebelum range restriction dan outlier = ${v.r}. Observed r berubah karena sampling variation dan manipulasi data.</p>`:''}${v.shape==='U-shaped'?note('U-shaped relationship dapat kuat secara visual walaupun correlation coefficient mendekati nol. Zero correlation tidak sama dengan no relationship.'):''}${v.range<100?`<p>Hanya ${v.range}% central X range yang dipertahankan; range restriction memengaruhi observed r.</p>`:''}${v.outlier?`<p>Dengan outlier, r = ${fmt(d.r)}. Tanpa outlier, r = <strong>${fmt(d.without)}</strong>.</p>`:''}<p>Correlation adalah association, bukan bukti causation. Selalu periksa scatterplot.</p>`)}${dataBox('Simulated Bivariate Data (first 60)',d.export)}`},
 regression(d,v){let f=d.fit;return `${metrics([['Estimated intercept',fmt(f.b0)],['Estimated slope',fmt(f.b1),`Generating linear term = ${v.slope}`],['R²',fmt(f.r2)],['Slope p-value',sig(f.p)]])}<div class="viz-grid wide-left">${plotCard('regScatter','Observed Data & Fitted Line',`Generating relationship: ${v.shape}`,'tall')}${plotCard('regResiduals','Residual Plot','Look for curvature or changing spread','tall')}</div>${interpret(`<p>Fitted equation: <strong>Ŷ = ${fmt(f.b0,2)} + ${fmt(f.b1,2)}X</strong>, R² = ${fmt(f.r2)}, slope p ${sig(f.p)}.</p><p>At X = ${v.x0}, predicted mean response <strong>${fmt(d.pred)}</strong>. 95% CI for mean response: [${fmt(d.conf[0])}, ${fmt(d.conf[1])}]; 95% Prediction Interval: [${fmt(d.pi[0])}, ${fmt(d.pi[1])}].</p>${v.shape!=='Linear'?note('Generating relationship mengandung komponen quadratic yang tidak dimasukkan ke fitted linear model. Cek residual plot untuk curvature.'):''}${v.hetero>0?'<p>Heteroscedasticity aktif, sehingga standard error OLS konvensional dapat tidak sesuai untuk inferensi.</p>':''}<p>Prediction Interval biasanya lebih lebar daripada CI mean response karena turut mencakup individual residual variability.</p>`)}${dataBox('Coefficients & Prediction',d.table)}${dataBox('Regression Observations (first 60)',d.export)}`},
 ttest(d,v){let desc=d.desc;return `${metrics([['t statistic',fmt(d.t)],['df',fmt(d.df,2)],['p-value',sig(d.p)],[v.type==='Paired samples'?"Cohen's dz":"Cohen's d",fmt(d.d)]])}<div class="viz-grid wide-left">${plotCard('ttPlot','Observed Sample Data',v.type,'tall')}${dataBox('Descriptive Statistics',desc)}</div>${dataBox('Test Results',[{Statistic:d.label,Value:d.estimate},{Statistic:'t',Value:d.t},{Statistic:'df',Value:d.df},{Statistic:'p-value',Value:d.p},{Statistic:`${pct(v.conf,0)} CI lower`,Value:d.ci[0]},{Statistic:`${pct(v.conf,0)} CI upper`,Value:d.ci[1]},{Statistic:v.type==='Paired samples'?"Cohen's dz":"Cohen's d",Value:d.d}])}${interpret(`<p>Observed ${d.label.toLowerCase()} = <strong>${fmt(d.estimate)}</strong>. t = <strong>${fmt(d.t)}</strong>, df = ${fmt(d.df,2)}, p ${sig(d.p)}.</p><p>${pct(v.conf,0)} Confidence Interval: <strong>[${fmt(d.ci[0])}, ${fmt(d.ci[1])}]</strong>.</p><p>${v.type==='Independent samples'?`Metode: <strong>${v.method}</strong>. Cohen’s d menggunakan pooled SD.`:v.type==='Paired samples'?'Effect size adalah Cohen’s dz, menggunakan SD difference scores.':'Effect size adalah Cohen’s d, menggunakan sample SD.'}</p>${note('Hasil nonsignificant tidak membuktikan H0 benar. Perhatikan CI, effect size, desain penelitian, dan statistical power.')}`)}${dataBox('Simulated Observations (first 60)',d.export)}`},
 anova(d,v){return `${metrics([['F statistic',fmt(d.F)],['p-value',sig(d.p)],['Eta squared',fmt(d.eta2)],['Omega squared',fmt(d.omega2)]])}<div class="viz-grid wide-left">${plotCard('anovaGroups','Observed Data by Group','Diamond = sample mean; X = population mean','tall')}${plotCard('anovaMS','ANOVA Decomposition','F = MS Between / MS Within','tall')}</div>${dataBox('ANOVA Table',d.table)}${dataBox('Tukey HSD Post Hoc (interpolated)',d.tukey)}${dataBox('Group Descriptive Statistics',d.descs)}${interpret(`<p>Generating population means: <strong>${d.means.map(m=>fmt(m,1)).join(', ')}</strong>.</p><p>MS Between = ${fmt(d.msb,2)}, MS Within = ${fmt(d.msw,2)}, sehingga F(${d.dfb}, ${d.dfw}) = <strong>${fmt(d.F,3)}</strong> dan p ${sig(d.p)}. ${d.p<v.alpha?'Equal-means H0 ditolak pada alpha terpilih.':'Belum ada bukti cukup untuk menolak equal-means H0 pada alpha terpilih.'}</p><p>Eta squared = <strong>${fmt(d.eta2)}</strong>, omega squared = <strong>${fmt(d.omega2)}</strong>. Perbandingan pairwise menggunakan Tukey HSD dengan interpolasi studentized range, sehingga p-adjusted adalah numerically approximated.</p>${note('Significant omnibus ANOVA tidak berarti semua pasangan berbeda. Bandingkan hasil Tukey dengan pola mean tiap grup.')}`)}${dataBox('Simulated Data (first 60)',d.export)}`}
};
function smoothLoess(x,y,gx,bandwidth=.35){let n=x.length,nNear=Math.max(7,Math.round(n*bandwidth));return gx.map(xx=>{let distances=x.map(xv=>Math.abs(xv-xx)).sort((a,b)=>a-b),h=Math.max(1e-9,distances[Math.min(nNear-1,n-1)]);let sw=0,sx=0,sy=0,sxx=0,sxy=0;for(let i=0;i<n;i++){let u=Math.abs(x[i]-xx)/h,w=u>=1?0:(1-u**3)**3;sw+=w;sx+=w*x[i];sy+=w*y[i];sxx+=w*x[i]**2;sxy+=w*x[i]*y[i]}let denom=sw*sxx-sx*sx;return denom>1e-12?(sy*sxx-sx*sxy+(sw*sxy-sx*sy)*xx)/denom:sy/sw})}
function linspace(a,b,n=100){return Array.from({length:n},(_,i)=>a+(b-a)*i/(n-1))}
function rangeVals(x,pad=.1){let lo=Math.min(...x),hi=Math.max(...x),d=(hi-lo||1)*pad;return[lo-d,hi+d]}
function groupBox(groups,meanPoints=true,truth=[]){let p=P(),out=groups.map(g=>({type:'box',name:g.name,y:g.values,boxpoints:'all',jitter:.36,pointpos:0,marker:{color:p.point,size:4,opacity:.48},line:{color:p.blue},fillcolor:p.fill,whiskerwidth:.5,showlegend:false}));if(meanPoints)out.push({type:'scatter',mode:'markers',x:groups.map(g=>g.name),y:groups.map(g=>S.mean(g.values)),marker:{symbol:'diamond',size:12,color:p.amber},name:'Sample mean',hovertemplate:'Mean %{y:.3f}<extra></extra>'});if(truth.length)out.push({type:'scatter',mode:'markers',x:groups.map(g=>g.name),y:truth,marker:{symbol:'x',size:11,color:p.teal,line:{width:2}},name:'Population mean',hovertemplate:'Population %{y:.3f}<extra></extra>'});return out}
const renderPlots={
 sampling(d,v){let p=P();chart('sampPop',[histTrace(d.population,45)],{xaxis:{title:'Value',gridcolor:p.grid},yaxis:{title:'Count',gridcolor:p.grid},shapes:[vline(d.target,p.blue)]});let sampleVal=v.stat==='Mean'?S.mean(d.one):S.median(d.one);chart('sampOne',[histTrace(d.one,Math.min(20,Math.max(6,Math.floor(Math.sqrt(v.n)))))],{xaxis:{title:'Value',gridcolor:p.grid},yaxis:{title:'Count',gridcolor:p.grid},shapes:[vline(sampleVal,p.fg,'solid'),vline(d.target,p.blue)]});chart('sampSim',[histTrace(d.stats,40)],{xaxis:{title:v.stat,gridcolor:p.grid},yaxis:{title:'Count',gridcolor:p.grid},shapes:[vline(d.target,p.blue)]})},
 ci(d,v){let p=P(),rows=d.rows.slice(0,100),linesX=[],linesY=[],coveredX=[],coveredY=[],missedX=[],missedY=[];for(let r of rows){linesX.push(r.iteration,r.iteration,null);linesY.push(r.lower,r.upper,null);(r.covered?coveredX:missedX).push(r.iteration);(r.covered?coveredY:missedY).push(r.mean)}chart('ciPlot',[{type:'scatter',mode:'lines',x:linesX,y:linesY,line:{color:p.muted,width:1.2},hoverinfo:'skip'},{type:'scatter',mode:'markers',x:coveredX,y:coveredY,name:'Covered',marker:{size:6,color:p.blue}},{type:'scatter',mode:'markers',x:missedX,y:missedY,name:'Missed',marker:{size:7,color:p.red}}],{showlegend:true,legend:{orientation:'h',x:0,y:1.13},xaxis:{title:'Repeated sample',gridcolor:p.grid},yaxis:{title:'Estimated mean and CI',gridcolor:p.grid},shapes:[hline(v.mu,p.fg)]})},
 pvalue(d,v){let p=P();function single(){let i=Math.min(d.rows.length,Math.max(1,Number(el('studyInput').value)))-1,r=d.rows[i],obs=r.t,df=r.df,crit=S.studentInv(1-v.alpha/2,df),lim=Math.max(4,Math.abs(obs)+.75),xs=linspace(-lim,lim,600),ys=xs.map(t=>S.studentPDF(t,df)),tailLeftX=xs.filter(t=>t<=-Math.abs(obs)),tailRightX=xs.filter(t=>t>=Math.abs(obs));el('studyLabel').textContent=i+1;el('studyMetrics').innerHTML=metrics([['Study',String(i+1)],['Observed t',fmt(obs)],['p-value',sig(r.p)],['Decision',r.p<v.alpha?'Significant':'Not significant',`alpha = ${v.alpha}`]]);let tails=xx=>({type:'scatter',x:xx,y:xx.map(t=>S.studentPDF(t,df)),fill:'tozeroy',fillcolor:p.fill,mode:'lines',line:{width:0,color:p.blue},hoverinfo:'skip'});chart('pvSingle',[tails(tailLeftX),tails(tailRightX),line(xs,ys,p.fg)],{xaxis:{title:'t under H₀',gridcolor:p.grid},yaxis:{title:'Density',gridcolor:p.grid},shapes:[vline(obs,p.amber,'solid'),vline(-crit,p.blue),vline(crit,p.blue)]})}el('studyInput').addEventListener('input',single);single();chart('pvHist',[histTrace(d.rows.map(r=>r.p),40)],{xaxis:{title:'p-value',range:[0,1],gridcolor:p.grid},yaxis:{title:'Number of studies',gridcolor:p.grid},shapes:[vline(v.alpha,p.blue)]});chart('pvEffects',[histTrace(d.rows.map(r=>r.estimate),40)],{xaxis:{title:'Estimated mean difference',gridcolor:p.grid},yaxis:{title:'Number of studies',gridcolor:p.grid},shapes:[vline(v.d,p.blue)]})},
 power(d,v){let p=P();chart('powN',[line(d.ns,d.powersN,p.blue)],{xaxis:{title:v.test==='Paired t-test'?'Number of pairs':'Sample size per group',gridcolor:p.grid},yaxis:{title:'Power',range:[0,1],tickformat:'.0%',gridcolor:p.grid},shapes:[hline(v.target,p.fg),vline(v.n,p.amber,'dot')]});chart('powE',[line(d.effects,d.powersE,p.teal)],{xaxis:{title:v.test==='One-way ANOVA'?"Cohen's f":v.test==='Paired t-test'?"Cohen's dz":"Cohen's d",gridcolor:p.grid},yaxis:{title:'Power',range:[0,1],tickformat:'.0%',gridcolor:p.grid},shapes:[hline(v.target,p.fg),vline(v.effect,p.amber,'dot')]})},
 correlation(d,v){let p=P(),xy=d.x.map((x,i)=>({x,y:d.y[i],out:d.point[i]==='Outlier'})),regular=xy.filter(d=>!d.out),outliers=xy.filter(d=>d.out),gx=linspace(Math.min(...d.x),Math.max(...d.x),110),fitY=gx.map(x=>d.fit.b0+d.fit.b1*x);let traces=[scatter(regular.map(t=>t.x),regular.map(t=>t.y),p.point)];if(outliers.length)traces.push(scatter(outliers.map(t=>t.x),outliers.map(t=>t.y),p.red,{symbol:'x',size:12,line:{width:2}}));traces.push(line(gx,fitY,p.blue));if(v.shape!=='Linear')traces.push(line(gx,smoothLoess(d.x,d.y,gx,.38),p.teal,{dash:'dash'}));chart('corrScatter',traces,{xaxis:{title:'X',gridcolor:p.grid},yaxis:{title:'Y',gridcolor:p.grid}});chart('corrBoot',[histTrace(d.boots,35)],{xaxis:{title:'Bootstrap Pearson r',gridcolor:p.grid},yaxis:{title:'Count',gridcolor:p.grid},shapes:[vline(d.r,p.blue)]})},
 regression(d,v){let p=P(),f=d.fit,regular=d.x.map((x,i)=>({x,y:d.y[i],out:d.point[i]==='Outlier'})).filter(a=>!a.out),out=d.x.map((x,i)=>({x,y:d.y[i],out:d.point[i]==='Outlier'})).filter(a=>a.out),gx=linspace(Math.min(...d.x),Math.max(...d.x),120),yl=gx.map(x=>f.b0+f.b1*x),tc=S.studentInv(.975,f.df),up=gx.map((x,i)=>yl[i]+tc*Math.sqrt(f.s2*(1/d.x.length+(x-f.mx)**2/f.sxx))),low=gx.map((x,i)=>yl[i]-tc*Math.sqrt(f.s2*(1/d.x.length+(x-f.mx)**2/f.sxx)));let traces=[{type:'scatter',mode:'lines',x:[...gx,...[...gx].reverse()],y:[...up,...[...low].reverse()],fill:'toself',fillcolor:p.fill,line:{width:0,color:p.blue},hoverinfo:'skip'},scatter(regular.map(a=>a.x),regular.map(a=>a.y),p.point)];if(out.length)traces.push(scatter(out.map(a=>a.x),out.map(a=>a.y),p.red,{symbol:'x',size:12}));traces.push(line(gx,yl,p.blue));if(v.shape!=='Linear')traces.push(line(gx,gx.map(x=>v.intercept+v.slope*x+d.quad*x*x),p.teal,{dash:'dash'}));chart('regScatter',traces,{xaxis:{title:'X',gridcolor:p.grid},yaxis:{title:'Y',gridcolor:p.grid},shapes:[vline(v.x0,p.amber,'dot')]});let xx=f.fitted,rr=f.resid,gxx=linspace(Math.min(...xx),Math.max(...xx),100);chart('regResiduals',[scatter(xx,rr,p.point),line(gxx,smoothLoess(xx,rr,gxx,.4),p.teal,{dash:'dot'})],{xaxis:{title:'Fitted value',gridcolor:p.grid},yaxis:{title:'Residual',gridcolor:p.grid},shapes:[hline(0,p.fg)]})},
 ttest(d,v){let p=P(),tr=groupBox(d.groups);if(v.type==='Paired samples'){let g0=d.groups[0],g1=d.groups[1],lx=[],ly=[];for(let i=0;i<g0.values.length;i++){lx.push(g0.name,g1.name,null);ly.push(g0.values[i],g1.values[i],null)}tr.unshift({type:'scatter',x:lx,y:ly,mode:'lines',line:{color:p.muted,width:.7},opacity:.45,hoverinfo:'skip'});}chart('ttPlot',tr,{xaxis:{gridcolor:p.grid},yaxis:{title:'Observed values',gridcolor:p.grid}})},
 anova(d,v){let p=P();chart('anovaGroups',groupBox(d.groups,true,d.means),{xaxis:{gridcolor:p.grid},yaxis:{title:'Value',gridcolor:p.grid}});chart('anovaMS',[{type:'bar',x:['MS Between','MS Within'],y:[d.msb,d.msw],marker:{color:[p.blue,p.teal]},text:[fmt(d.msb,2),fmt(d.msw,2)],textposition:'outside',cliponaxis:false}],{xaxis:{gridcolor:p.grid},yaxis:{title:'Mean Square',gridcolor:p.grid,range:[0,Math.max(d.msb,d.msw)*1.18]}})}
};
function setTheme(theme){state.theme=theme;document.documentElement.classList.toggle('dark',theme==='dark');localStorage.setItem('statslab-theme',theme);el('themeToggle').innerHTML=theme==='dark'?'☀ <span>Light</span>':'☾ <span>Dark</span>';if(modules[state.page]&&state.data[state.page])renderPlots[state.page](state.data[state.page],state.values[state.page]);}
function boot(){if(typeof Plotly==='undefined'){el('main').innerHTML='<div class="error-panel">Plotting engine gagal dimuat. Pastikan folder assets/plotly.min.js ikut di-upload.</div>';return;}setTheme(state.theme);document.querySelectorAll('.nav-item[data-page],.mobile-tabs [data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));el('themeToggle').addEventListener('click',()=>setTheme(state.theme==='dark'?'light':'dark'));el('allModulesButton').addEventListener('click',()=>el('sidebar').classList.toggle('show'));el('main').addEventListener('click',e=>{let btn=e.target.closest('[data-open]');if(btn)go(btn.dataset.open);});window.addEventListener('hashchange',()=>go(location.hash.substring(1),false));go(location.hash.substring(1)||'home',false);}
window.addEventListener('DOMContentLoaded',boot);
